```dart
import 'package:duxt_orm/duxt_orm.dart';

class User extends Model {
  @override
  String get tableName => 'users';

  @override
  Map<String, ColumnType> get schema => {
    'email': ColumnType.text,
    'password': ColumnType.text,
    'name': ColumnType.text,
  };

  String? email;
  String? password;
  String? name;

  @override
  void fromMap(Map<String, dynamic> map) {
    super.fromMap(map);
    email = map['email'] as String?;
    password = map['password'] as String?;
    name = map['name'] as String?;
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      ...super.toMap(),
      'email': email,
      'password': password,
      'name': name,
    };
  }

  /// Return a safe representation without the password hash
  Map<String, dynamic> toSafeMap() {
    return {
      'id': id,
      'email': email,
      'name': name,
      'created_at': createdAt?.toIso8601String(),
      'updated_at': updatedAt?.toIso8601String(),
    };
  }
}
```

Key design decisions:
- `toSafeMap()` is a custom helper that excludes the password hash from API responses. This prevents accidentally leaking sensitive data.
- The `super.fromMap(map)` / `super.toMap()` calls handle the base fields `id`, `created_at`, `updated_at` that the ORM provides automatically.

