41→    if (id == null) return json({'error': 'Invalid ID'}, statusCode: 400);
42→
43→    final body = req.body as Map<String, dynamic>?;
44→    if (body == null) return json({'error': 'Body required'}, statusCode: 400);
45→
46→    final post = await Model<Post>().find(id);
47→    if (post == null) return json({'error': 'Not found'}, statusCode: 404);
48→
49→    // Update fields
