62→    final id = int.tryParse(req.params['id'] ?? '');
63→    if (id == null) return json({'error': 'Invalid ID'}, statusCode: 400);
64→
65→    final post = await Model<Post>().find(id);
66→    if (post == null) return json({'error': 'Not found'}, statusCode: 404);
67→
68→    await post.destroy();
69→    return json({'success': true});
70→  });
