 72→  Future<Response> _handleApi(
 73→    Request request,
 74→    Future<ApiResponse> Function(ApiRequest) handler,
 75→  ) async {
 76→    final body = await request.readAsString();
 77→    final apiRequest = ApiRequest(
 78→      method: request.method,
 79→      path: request.url.path,
 80→      params: {}, // Will be populated by router
 81→      query: request.url.queryParameters,
 82→      headers: request.headers,
 83→      body: body,
 84→    );
 85→
 86→    try {
 87→      final apiResponse = await handler(apiRequest);
 88→      return Response(
 89→        apiResponse.statusCode,
 90→        body: apiResponse.toJson(),
 91→        headers: {
 92→          'Content-Type': 'application/json',
 93→          ...apiResponse.headers,
 94→        },
 95→      );
 96→    } catch (e) {
 97→      // Log full error server-side, return generic message to client
 98→      print('\x1B[31m[error]\x1B[0m API handler failed: $e');
 99→      return Response.internalServerError(
100→        body: jsonEncode({'error': 'Internal server error'}),
101→        headers: {
102→          'Content-Type': 'application/json',
103→          'X-Content-Type-Options': 'nosniff',
104→        },
105→      );
106→    }
