184→  /// Match route pattern to path
185→  Map<String, String>? _matchRoute(String pattern, String path) {
186→    final patternParts = pattern.split('/').where((p) => p.isNotEmpty).toList();
187→    final pathParts = path.split('/').where((p) => p.isNotEmpty).toList();
188→
189→    if (patternParts.length != pathParts.length) return null;
190→
191→    final params = <String, String>{};
192→    for (var i = 0; i < patternParts.length; i++) {
193→      final patternPart = patternParts[i];
194→      final pathPart = pathParts[i];
195→
196→      if (patternPart.startsWith(':')) {
197→        params[patternPart.substring(1)] = pathPart;
198→      } else if (patternPart != pathPart) {
199→        return null;
200→      }
201→    }
202→    return params;
203→  }
