430→/// CSRF protection middleware
431→///
432→/// Validates that state-changing requests (POST, PUT, DELETE, PATCH) include
433→/// a matching CSRF token in the header. GET/HEAD/OPTIONS are always allowed.
434→Middleware csrf({String headerName = 'X-CSRF-Token', String cookieName = 'csrf_token'}) {
435→  return (Handler innerHandler) {
436→    return (Request request) async {
437→      final safeMethods = {'GET', 'HEAD', 'OPTIONS'};
438→      if (safeMethods.contains(request.method)) {
439→        return innerHandler(request);
440→      }
441→
442→      final cookieHeader = request.headers['cookie'] ?? '';
443→      final cookies = _parseCookies(cookieHeader);
444→      final cookieToken = cookies[cookieName];
445→      final headerToken = request.headers[headerName.toLowerCase()];
446→
447→      if (cookieToken == null || cookieToken.isEmpty ||
448→          headerToken == null || headerToken != cookieToken) {
449→        return Response.forbidden(
450→          jsonEncode({'error': 'CSRF token mismatch'}),
451→          headers: {'Content-Type': 'application/json'},
452→        );
453→      }
454→
455→      return innerHandler(request);
456→    };
457→  };
458→}
459→
460→Map<String, String> _parseCookies(String cookieHeader) {
461→  final cookies = <String, String>{};
462→  for (final part in cookieHeader.split(';')) {
463→    final trimmed = part.trim();
464→    final eq = trimmed.indexOf('=');
465→    if (eq > 0) {
466→      cookies[trimmed.substring(0, eq)] = trimmed.substring(eq + 1);
467→    }
468→  }
469→  return cookies;
470→}
471→
472→/// Extension to get parsed data from request
473→extension RequestExtensions on Request {
474→  /// Get route parameters
475→  Map<String, String> get params => context['params'] as Map<String, String>? ?? {};
476→
477→  /// Get a route parameter
478→  String? param(String key) => params[key];
479→
480→  /// Get parsed JSON body
481→  dynamic get body => context['body'];
482→
483→  /// Get raw body string (before JSON parsing)
484→  String? get rawBody => context['rawBody'] as String?;
485→
486→  /// Get query parameter
487→  String? query(String key) => url.queryParameters[key];
488→}
489→
490→/// Helper to create a JSON response
491→Response json(dynamic data, {int statusCode = 200, Map<String, String>? headers}) {
492→  return Response(
493→    statusCode,
494→    body: jsonEncode(data),
495→    headers: {
496→      'Content-Type': 'application/json',
497→      ...?headers,
498→    },
499→  );
500→}
