 11→/// Duxt Server - Shelf-based HTTP server
 12→class DuxtServer {
 13→  final int port;
 14→  final String apiDir;
 15→  final String? staticDir;
 16→  final List<Middleware> middleware;
 17→  final Duration requestTimeout;
 18→  final Map<String, Handler> _routes = {};
 19→  HttpServer? _server;
 20→  StreamSubscription? _sigintSub;
 21→  StreamSubscription? _sigtermSub;
 22→
 23→  DuxtServer({
 24→    this.port = 3000,
 25→    this.apiDir = 'server/api',
 26→    this.staticDir,
 27→    this.middleware = const [],
 28→    this.requestTimeout = const Duration(seconds: 30),
 29→  });
 30→
 31→  /// Register a GET route
 32→  void get(String path, Handler handler) {
 33→    _routes['GET:$path'] = handler;
 34→  }
 35→
 36→  /// Register a POST route
 37→  void post(String path, Handler handler) {
 38→    _routes['POST:$path'] = handler;
 39→  }
 40→
 41→  /// Register a PUT route
 42→  void put(String path, Handler handler) {
 43→    _routes['PUT:$path'] = handler;
 44→  }
 45→
 46→  /// Register a DELETE route
 47→  void delete(String path, Handler handler) {
 48→    _routes['DELETE:$path'] = handler;
 49→  }
 50→
 51→  /// Register a PATCH route
 52→  void patch(String path, Handler handler) {
 53→    _routes['PATCH:$path'] = handler;
 54→  }
 55→
 56→  /// Register any method
 57→  void all(String path, Handler handler) {
 58→    for (final method in ['GET', 'POST', 'PUT', 'DELETE', 'PATCH']) {
 59→      _routes['$method:$path'] = handler;
 60→    }
 61→  }
 62→
 63→  /// Register an API handler class
 64→  void use(String path, ApiHandler handler) {
 65→    get(path, (req) => _handleApi(req, handler.get));
 66→    post(path, (req) => _handleApi(req, handler.post));
 67→    put(path, (req) => _handleApi(req, handler.put));
 68→    delete(path, (req) => _handleApi(req, handler.delete));
 69→    patch(path, (req) => _handleApi(req, handler.patch));
 70→  }
 71→
 72→  Future<Response> _handleApi(
 73→    Request request,
 74→    Future<ApiResponse> Function(ApiRequest) handler,
 75→  ) async {
 76→    final body = await request.readAsString();
 77→    final apiRequest = ApiRequest(
 78→      method: request.method,
 79→      path: request.url.path,
 80→      params: {}, // Will be populated by router
 81→      query: request.url.queryParameters,
 82→      headers: request.headers,
 83→      body: body,
 84→    );
 85→
 86→    try {
 87→      final apiResponse = await handler(apiRequest);
 88→      return Response(
 89→        apiResponse.statusCode,
 90→        body: apiResponse.toJson(),
 91→        headers: {
 92→          'Content-Type': 'application/json',
 93→          ...apiResponse.headers,
 94→        },
 95→      );
 96→    } catch (e) {
 97→      // Log full error server-side, return generic message to client
 98→      print('\x1B[31m[error]\x1B[0m API handler failed: $e');
 99→      return Response.internalServerError(
100→        body: jsonEncode({'error': 'Internal server error'}),
101→        headers: {
102→          'Content-Type': 'application/json',
103→          'X-Content-Type-Options': 'nosniff',
104→        },
105→      );
106→    }
107→  }
108→
109→  /// Main request handler
110→  Handler get handler {
111→    return (Request request) async {
112→      final method = request.method;
113→      final path = '/${request.url.path}';
114→
115→      // Try exact match
116→      final key = '$method:$path';
117→      if (_routes.containsKey(key)) {
118→        return _routes[key]!(request);
119→      }
120→
121→      // Try pattern matching for dynamic routes
122→      for (final entry in _routes.entries) {
123→        final routeKey = entry.key;
124→        if (!routeKey.startsWith('$method:')) continue;
125→
126→        final routePath = routeKey.substring(method.length + 1);
127→        final params = _matchRoute(routePath, path);
128→        if (params != null) {
129→          // Add params to request context
130→          final newRequest = request.change(context: {
131→            ...request.context,
132→            'params': params,
133→          });
134→          return entry.value(newRequest);
135→        }
136→      }
137→
138→      // Try serving static files if staticDir is set
139→      if (staticDir != null) {
140→        final staticHandler = createStaticHandler(
141→          staticDir!,
142→          defaultDocument: 'index.html',
143→        );
144→        final staticResponse = await staticHandler(request);
145→        if (staticResponse.statusCode != 404) {
146→          return staticResponse;
147→        }
148→        // For SPA routing, try serving index.html for HTML requests
149→        if (request.headers['accept']?.contains('text/html') ?? false) {
150→          final indexFile = File('$staticDir/index.html');
151→          if (indexFile.existsSync()) {
152→            return Response.ok(
153→              indexFile.readAsStringSync(),
154→              headers: {'Content-Type': 'text/html'},
155→            );
156→          }
157→        }
158→      }
159→
160→      // Content-negotiated 404: HTML for browsers, JSON for API clients
161→      final accept = request.headers['accept'] ?? '';
162→      if (accept.contains('text/html')) {
163→        return Response.notFound(
164→          DuxtErrorHtml.notFound(path: path),
165→          headers: {
166→            'Content-Type': 'text/html',
167→            'Vary': 'Accept',
168→            'X-Content-Type-Options': 'nosniff',
169→            'X-Frame-Options': 'DENY',
170→          },
171→        );
172→      }
173→      return Response.notFound(
174→        jsonEncode({'error': 'Not found'}),
175→        headers: {
176→          'Content-Type': 'application/json',
177→          'Vary': 'Accept',
178→          'X-Content-Type-Options': 'nosniff',
179→        },
180→      );
181→    };
182→  }
183→
184→  /// Match route pattern to path
185→  Map<String, String>? _matchRoute(String pattern, String path) {
186→    final patternParts = pattern.split('/').where((p) => p.isNotEmpty).toList();
187→    final pathParts = path.split('/').where((p) => p.isNotEmpty).toList();
188→
189→    if (patternParts.length != pathParts.length) return null;
190→
191→    final params = <String, String>{};
192→    for (var i = 0; i < patternParts.length; i++) {
193→      final patternPart = patternParts[i];
194→      final pathPart = pathParts[i];
195→
196→      if (patternPart.startsWith(':')) {
197→        params[patternPart.substring(1)] = pathPart;
198→      } else if (patternPart != pathPart) {
199→        return null;
200→      }
201→    }
202→    return params;
203→  }
204→
205→  /// Build the pipeline with middleware
206→  Handler get pipeline {
207→    var h = handler;
208→    for (final m in middleware.reversed) {
209→      h = m(h);
210→    }
211→    return h;
212→  }
213→
214→  /// Start the server
215→  Future<void> start() async {
216→    _server = await shelf_io.serve(pipeline, InternetAddress.anyIPv4, port);
217→    _server!.idleTimeout = requestTimeout;
218→    print('Server running at http://localhost:$port');
219→
220→    // Graceful shutdown on SIGINT and SIGTERM
221→    _sigintSub = ProcessSignal.sigint.watch().listen((_) => _shutdown());
222→    if (!Platform.isWindows) {
223→      _sigtermSub = ProcessSignal.sigterm.watch().listen((_) => _shutdown());
224→    }
225→  }
226→
227→  Future<void> _shutdown() async {
228→    print('\nShutting down gracefully...');
229→    await stop();
230→    exit(0);
231→  }
232→
233→  /// Stop the server
234→  Future<void> stop() async {
235→    _sigintSub?.cancel();
236→    _sigtermSub?.cancel();
237→    await _server?.close();
238→    _server = null;
239→  }
240→}
