242→/// CORS middleware
243→///
244→/// By default, no origins are allowed. You must explicitly specify allowed origins.
245→/// Use `origins: ['*']` only for public APIs — never for authenticated endpoints.
246→Middleware cors({
247→  required List<String> origins,
248→  List<String> methods = const ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
249→  List<String> headers = const ['Content-Type', 'Authorization'],
250→}) {
251→  return (Handler innerHandler) {
252→    return (Request request) async {
253→      final origin = request.headers['origin'] ?? '';
254→      final allowedOrigin = origins.contains('*') ? '*' : (origins.contains(origin) ? origin : null);
255→
256→      if (request.method == 'OPTIONS') {
257→        return Response.ok('', headers: {
258→          if (allowedOrigin != null) 'Access-Control-Allow-Origin': allowedOrigin,
259→          'Access-Control-Allow-Methods': methods.join(', '),
260→          'Access-Control-Allow-Headers': headers.join(', '),
261→        });
262→      }
263→
264→      final response = await innerHandler(request);
265→      return response.change(headers: {
266→        ...response.headers,
267→        if (allowedOrigin != null) 'Access-Control-Allow-Origin': allowedOrigin,
268→      });
269→    };
270→  };
271→}
272→
273→/// Security headers middleware — adds standard security headers to all responses
274→Middleware securityHeaders() {
275→  return (Handler innerHandler) {
276→    return (Request request) async {
277→      final response = await innerHandler(request);
278→      return response.change(headers: {
279→        ...response.headers,
280→        'X-Content-Type-Options': 'nosniff',
281→        'X-Frame-Options': 'DENY',
282→        'X-XSS-Protection': '1; mode=block',
283→        'Referrer-Policy': 'strict-origin-when-cross-origin',
284→      });
285→    };
286→  };
287→}
288→
289→/// Request body size limit middleware
290→///
291→/// Rejects requests with Content-Length exceeding [maxBytes].
292→/// Default limit is 1 MB.
293→Middleware bodyLimit({int maxBytes = 1024 * 1024}) {
294→  return (Handler innerHandler) {
295→    return (Request request) async {
296→      final contentLength = request.contentLength;
297→      if (contentLength != null && contentLength > maxBytes) {
298→        return Response(
299→          413,
300→          body: jsonEncode({'error': 'Request body too large'}),
301→          headers: {'Content-Type': 'application/json'},
302→        );
303→      }
304→      return innerHandler(request);
305→    };
306→  };
307→}
308→
309→/// Rate limiting middleware
310→///
311→/// Limits each IP to [maxRequests] per [window]. Uses in-memory storage.
312→Middleware rateLimit({
313→  int maxRequests = 100,
314→  Duration window = const Duration(minutes: 1),
315→}) {
316→  final _requests = <String, List<DateTime>>{};
317→
318→  return (Handler innerHandler) {
319→    return (Request request) async {
320→      final ip = (request.context['shelf.io.connection_info'] as HttpConnectionInfo?)
321→          ?.remoteAddress.address ?? 'unknown';
322→      final now = DateTime.now();
323→      final cutoff = now.subtract(window);
324→
325→      // Clean old entries and add current
326→      final timestamps = (_requests[ip] ?? [])
327→          .where((t) => t.isAfter(cutoff))
328→          .toList()
329→        ..add(now);
330→      _requests[ip] = timestamps;
331→
332→      if (timestamps.length > maxRequests) {
333→        return Response(
334→          429,
335→          body: jsonEncode({'error': 'Too many requests'}),
336→          headers: {
337→            'Content-Type': 'application/json',
338→            'Retry-After': window.inSeconds.toString(),
339→          },
340→        );
341→      }
342→
343→      return innerHandler(request);
344→    };
345→  };
346→}
347→
348→/// Request timeout middleware
349→///
350→/// Returns 504 Gateway Timeout if the handler takes longer than [duration].
351→Middleware timeout({Duration duration = const Duration(seconds: 30)}) {
352→  return (Handler innerHandler) {
353→    return (Request request) async {
354→      try {
355→        return await Future.any<Response>([
356→          Future(() async => await innerHandler(request)),
357→          Future.delayed(duration, () => Response(
358→            504,
359→            body: jsonEncode({'error': 'Request timeout'}),
360→            headers: {'Content-Type': 'application/json'},
361→          )),
362→        ]);
363→      } catch (e) {
364→        return Response.internalServerError(
365→          body: jsonEncode({'error': 'Internal server error'}),
366→          headers: {'Content-Type': 'application/json'},
367→        );
368→      }
369→    };
370→  };
371→}
372→
373→/// JSON body parser middleware
374→Middleware jsonBody() {
375→  return (Handler innerHandler) {
376→    return (Request request) async {
377→      if (request.method == 'GET' || request.method == 'HEAD') {
378→        return innerHandler(request);
379→      }
380→
381→      final contentType = request.headers['content-type'] ?? '';
382→      if (!contentType.contains('application/json')) {
383→        return innerHandler(request);
384→      }
385→
386→      final body = await request.readAsString();
387→      final json = body.isNotEmpty ? jsonDecode(body) : null;
388→
389→      return innerHandler(request.change(context: {
390→        ...request.context,
391→        'body': json,
392→        'rawBody': body,
393→      }));
394→    };
395→  };
396→}
397→
398→/// Logger middleware
399→Middleware logger() {
400→  return (Handler innerHandler) {
401→    return (Request request) async {
402→      final stopwatch = Stopwatch()..start();
403→      final response = await innerHandler(request);
404→      stopwatch.stop();
405→
406→      final status = response.statusCode;
407→      final color = status < 400 ? '\x1B[32m' : '\x1B[31m';
408→      print('${request.method} ${request.url.path} $color$status\x1B[0m ${stopwatch.elapsedMilliseconds}ms');
409→
410→      return response;
411→    };
412→  };
413→}
414→
415→/// Auth middleware
416→Middleware auth(Future<bool> Function(Request) verify) {
417→  return (Handler innerHandler) {
418→    return (Request request) async {
419→      if (!await verify(request)) {
420→        return Response.unauthorized(
421→          jsonEncode({'error': 'Unauthorized'}),
422→          headers: {'Content-Type': 'application/json'},
423→        );
424→      }
425→      return innerHandler(request);
426→    };
427→  };
428→}
