273→/// Security headers middleware — adds standard security headers to all responses
274→Middleware securityHeaders() {
275→  return (Handler innerHandler) {
276→    return (Request request) async {
277→      final response = await innerHandler(request);
278→      return response.change(headers: {
279→        ...response.headers,
280→        'X-Content-Type-Options': 'nosniff',
281→        'X-Frame-Options': 'DENY',
282→        'X-XSS-Protection': '1; mode=block',
283→        'Referrer-Policy': 'strict-origin-when-cross-origin',
284→      });
285→    };
286→  };
287→}
