  9→void registerAuthApi(DuxtServer server) {
 10→  // POST /api/auth/register
 11→  server.post('/api/auth/register', (req) async {
 12→    final body = req.json;
 13→    if (body == null) {
 14→      return ApiResponse.badRequest('Request body required');
 15→    }
 16→
 17→    final email = (body['email'] as String?)?.trim();
 18→    final password = body['password'] as String?;
 19→    final name = (body['name'] as String?)?.trim();
 20→
 21→    if (email == null || email.isEmpty) {
 22→      return ApiResponse.badRequest('Email is required');
 23→    }
 24→    if (password == null || password.length < 6) {
 25→      return ApiResponse.badRequest('Password must be at least 6 characters');
 26→    }
 27→    if (name == null || name.isEmpty) {
 28→      return ApiResponse.badRequest('Name is required');
 29→    }
 30→
 31→    // Check for existing user
 32→    final existing = await User.findByEmail(email);
 33→    if (existing != null) {
 34→      return ApiResponse.badRequest('Email already registered');
 35→    }
 36→
 37→    // Create user
 38→    final hashedPassword = PasswordHelper.hash(password);
 39→    final user = User(
 40→      email: email,
 41→      password: hashedPassword,
 42→      name: name,
 43→    );
 44→    await user.save();
 45→
 46→    // Create session
 47→    final token = await SessionManager.createSession(user.id as int);
 48→
 49→    return ApiResponse.created(
 50→      {'user': user.toSafeMap()},
 51→    ).withHeader('Set-Cookie', 'session_token=$token; $_cookieFlags');
 52→  });
 53→
 54→  // POST /api/auth/login
 55→  server.post('/api/auth/login', (req) async {
 56→    final body = req.json;
 57→    if (body == null) {
 58→      return ApiResponse.badRequest('Request body required');
 59→    }
 60→
 61→    final email = (body['email'] as String?)?.trim();
 62→    final password = body['password'] as String?;
 63→
 64→    if (email == null || email.isEmpty || password == null || password.isEmpty) {
 65→      return ApiResponse.badRequest('Email and password are required');
 66→    }
 67→
 68→    final user = await User.findByEmail(email);
 69→    if (user == null || !PasswordHelper.verify(password, user.password)) {
 70→      return ApiResponse.unauthorized('Invalid email or password');
 71→    }
 72→
 73→    final token = await SessionManager.createSession(user.id as int);
 74→
 75→    return ApiResponse.ok(
 76→      {'user': user.toSafeMap()},
 77→    ).withHeader('Set-Cookie', 'session_token=$token; $_cookieFlags');
 78→  });
 79→
 80→  // POST /api/auth/logout
 81→  server.post('/api/auth/logout', (req) async {
 82→    final authResult = await authMiddleware(req);
 83→    if (authResult != null) return authResult;
 84→
 85→    final cookieHeader = req.headers['cookie'] ?? '';
 86→    final token = _extractCookie(cookieHeader, 'session_token');
 87→    if (token != null) {
 88→      await SessionManager.deleteSession(token);
 89→    }
 90→
 91→    return ApiResponse.ok(
 92→      {'message': 'Logged out'},
 93→    ).withHeader(
 94→        'Set-Cookie', 'session_token=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0');
 95→  });
 96→
 97→  // GET /api/auth/me
 98→  server.get('/api/auth/me', (req) async {
 99→    final authResult = await authMiddleware(req);
100→    if (authResult != null) return authResult;
101→
102→    final user = req.context['user'] as User;
103→    return ApiResponse.ok({'user': user.toSafeMap()});
104→  });
105→}
106→
107→String? _extractCookie(String cookieHeader, String name) {
108→  final cookies = cookieHeader.split(';');
109→  for (final cookie in cookies) {
110→    final parts = cookie.trim().split('=');
111→    if (parts.length == 2 && parts[0].trim() == name) {
112→      return parts[1].trim();
113→    }
114→  }
115→  return null;
116→}
