     3→/// Base class for API route handlers
     4→/// Handles HTTP methods for server-side API routes
     5→abstract class ApiHandler {
     6→  /// Handle GET requests
     7→  Future<ApiResponse> get(ApiRequest request) async {
     8→    return ApiResponse.methodNotAllowed();
     9→  }
    10→
    11→  /// Handle POST requests
    12→  Future<ApiResponse> post(ApiRequest request) async {
    13→    return ApiResponse.methodNotAllowed();
    14→  }
    15→
    16→  /// Handle PUT requests
    17→  Future<ApiResponse> put(ApiRequest request) async {
    18→    return ApiResponse.methodNotAllowed();
    19→  }
    20→
    21→  /// Handle DELETE requests
    22→  Future<ApiResponse> delete(ApiRequest request) async {
    23→    return ApiResponse.methodNotAllowed();
    24→  }
    25→
    26→  /// Handle PATCH requests
    27→  Future<ApiResponse> patch(ApiRequest request) async {
    28→    return ApiResponse.methodNotAllowed();
    29→  }
    30→
    31→  /// Handle any method (catch-all)
    32→  Future<ApiResponse> handler(ApiRequest request) async {
    33→    switch (request.method) {
    34→      case 'GET':
    35→        return get(request);
    36→      case 'POST':
    37→        return post(request);
    38→      case 'PUT':
    39→        return put(request);
    40→      case 'DELETE':
    41→        return delete(request);
    42→      case 'PATCH':
    43→        return patch(request);
    44→      default:
    45→        return ApiResponse.methodNotAllowed();
    46→    }
    47→  }
    48→}
    49→
    50→/// Incoming API request
    51→class ApiRequest {
    52→  final String method;
    53→  final String path;
    54→  final Map<String, String> params;
    55→  final Map<String, String> query;
    56→  final Map<String, String> headers;
    57→  final String? body;
    58→
    59→  ApiRequest({
    60→    required this.method,
    61→    required this.path,
    62→    this.params = const {},
    63→    this.query = const {},
    64→    this.headers = const {},
    65→    this.body,
    66→  });
    67→
    68→  /// Parse body as JSON
    69→  dynamic get json {
    70→    if (body == null || body!.isEmpty) return null;
    71→    return jsonDecode(body!);
    72→  }
    73→
    74→  /// Get a specific query parameter
    75→  String? getQuery(String key) => query[key];
    76→
    77→  /// Get a specific path parameter
    78→  String? getParam(String key) => params[key];
    79→
    80→  /// Get a specific header
    81→  String? getHeader(String key) => headers[key.toLowerCase()];
    82→}
    83→
    84→/// API response
    85→class ApiResponse {
    86→  final int statusCode;
    87→  final dynamic data;
    88→  final Map<String, String> headers;
    89→
    90→  ApiResponse({
    91→    required this.statusCode,
    92→    this.data,
    93→    this.headers = const {},
    94→  });
    95→
    96→  /// Success response with JSON data
    97→  factory ApiResponse.json(dynamic data, {int statusCode = 200}) {
    98→    return ApiResponse(
    99→      statusCode: statusCode,
   100→      data: data,
   101→      headers: {'Content-Type': 'application/json'},
   102→    );
   103→  }
   104→
   105→  /// Success response
   106→  factory ApiResponse.ok([dynamic data]) {
   107→    return ApiResponse.json(data ?? {'success': true});
   108→  }
   109→
   110→  /// Created response (201)
   111→  factory ApiResponse.created([dynamic data]) {
   112→    return ApiResponse.json(data ?? {'success': true}, statusCode: 201);
   113→  }
   114→
   115→  /// No content response (204)
   116→  factory ApiResponse.noContent() {
   117→    return ApiResponse(statusCode: 204);
   118→  }
   119→
   120→  /// Bad request response (400)
   121→  factory ApiResponse.badRequest([String? message]) {
   122→    return ApiResponse.json(
   123→      {'error': message ?? 'Bad request'},
   124→      statusCode: 400,
   125→    );
   126→  }
   127→
   128→  /// Unauthorized response (401)
   129→  factory ApiResponse.unauthorized([String? message]) {
   130→    return ApiResponse.json(
   131→      {'error': message ?? 'Unauthorized'},
   132→      statusCode: 401,
   133→    );
   134→  }
   135→
   136→  /// Forbidden response (403)
   137→  factory ApiResponse.forbidden([String? message]) {
   138→    return ApiResponse.json(
   139→      {'error': message ?? 'Forbidden'},
   140→      statusCode: 403,
   141→    );
   142→  }
   143→
   144→  /// Not found response (404)
   145→  factory ApiResponse.notFound([String? message]) {
   146→    return ApiResponse.json(
   147→      {'error': message ?? 'Not found'},
   148→      statusCode: 404,
   149→    );
   150→  }
   151→
   152→  /// Method not allowed response (405)
   153→  factory ApiResponse.methodNotAllowed() {
   154→    return ApiResponse.json(
   155→      {'error': 'Method not allowed'},
   156→      statusCode: 405,
   157→    );
   158→  }
   159→
   160→  /// Internal server error response (500)
   161→  factory ApiResponse.error([String? message]) {
   162→    return ApiResponse.json(
   163→      {'error': message ?? 'Internal server error'},
   164→      statusCode: 500,
   165→    );
   166→  }
   167→
   168→  /// Redirect response
   169→  factory ApiResponse.redirect(String location, {bool permanent = false}) {
   170→    return ApiResponse(
   171→      statusCode: permanent ? 301 : 302,
   172→      headers: {'Location': location},
   173→    );
   174→  }
   175→
   176→  /// Convert to JSON string
   177→  String toJson() {
   178→    if (data == null) return '';
   179→    return jsonEncode(data);
   180→  }
   181→}
   182→
   183→/// Define an event handler (for API routes)
   184→typedef EventHandler = Future<ApiResponse> Function(ApiRequest request);
   185→
   186→/// Create an event handler
   187→EventHandler defineEventHandler(EventHandler handler) => handler;
   188→
   189→/// Read body as JSON
   190→Future<dynamic> readBody(ApiRequest request) async {
   191→  return request.json;
   192→}
   193→
   194→/// Get query parameters
   195→Map<String, String> getQuery(ApiRequest request) => request.query;
   196→
   197→/// Get a single query parameter
   198→String? getQueryParam(ApiRequest request, String key) => request.query[key];
   199→
   200→/// Get route parameters
   201→Map<String, String> getRouteParams(ApiRequest request) => request.params;
   202→
   203→/// Send a redirect
   204→ApiResponse sendRedirect(String location, {int statusCode = 302}) {
   205→  return ApiResponse(
   206→    statusCode: statusCode,
   207→    headers: {'Location': location},
   208→  );
   209→}
   210→
   211→/// Send an error
   212→ApiResponse sendError(int statusCode, String message) {
   213→  return ApiResponse.json({'error': message}, statusCode: statusCode);
   214→}
   215→
   216→/// Set response header
   217→ApiResponse setHeader(ApiResponse response, String name, String value) {
   218→  final newHeaders = Map<String, String>.from(response.headers);
   219→  newHeaders[name] = value;
   220→  return ApiResponse(
   221→    statusCode: response.statusCode,
   222→    data: response.data,
   223→    headers: newHeaders,
   224→  );
   225→}
