460→Map<String, String> _parseCookies(String cookieHeader) {
461→  final cookies = <String, String>{};
462→  for (final part in cookieHeader.split(';')) {
463→    final trimmed = part.trim();
464→    final eq = trimmed.indexOf('=');
465→    if (eq > 0) {
466→      cookies[trimmed.substring(0, eq)] = trimmed.substring(eq + 1);
467→    }
468→  }
469→  return cookies;
470→}
