     9→  server.get('/api/todos', (req) async {
    10→    final authResult = await authMiddleware(req);
    11→    if (authResult != null) return authResult;
    12→
    13→    final user = req.context['user'] as User;
    14→    final todos = await Model<Todo>()
    15→        .query()
    16→        .where('user_id', user.id)
    17→        .orderByDesc('created_at')
    18→        .get();
    19→
    20→    return ApiResponse.ok({
    21→      'todos': todos.map((t) => t.toJson()).toList(),
    22→    });
    23→  });
    24→
    25→  // POST /api/todos - Create a todo
    26→  server.post('/api/todos', (req) async {
    27→    final authResult = await authMiddleware(req);
    28→    if (authResult != null) return authResult;
    29→
    30→    final user = req.context['user'] as User;
    31→    final body = req.json;
    32→    if (body == null) {
    33→      return ApiResponse.badRequest('Request body required');
    34→    }
    35→
    36→    final title = (body['title'] as String?)?.trim();
    37→    if (title == null || title.isEmpty) {
    38→      return ApiResponse.badRequest('Title is required');
    39→    }
    40→
    41→    final todo = Todo(
    42→      title: title,
    43→      completed: body['completed'] as bool? ?? false,
    44→      userId: user.id as int,
    45→    );
    46→    await todo.save();
    47→
    48→    return ApiResponse.created({'todo': todo.toJson()});
    49→  });
    50→
    51→  // GET /api/todos/:id - Get a single todo
    52→  server.get('/api/todos/:id', (req) async {
    53→    final authResult = await authMiddleware(req);
    54→    if (authResult != null) return authResult;
    55→
    56→    final user = req.context['user'] as User;
    57→    final id = int.tryParse(req.params['id'] ?? '');
    58→    if (id == null) {
    59→      return ApiResponse.badRequest('Invalid ID');
    60→    }
    61→
    62→    final todo = await Model<Todo>().find(id);
    63→    if (todo == null || todo.userId != user.id) {
    64→      return ApiResponse.notFound('Todo not found');
    65→    }
    66→
    67→    return ApiResponse.ok({'todo': todo.toJson()});
    68→  });
    69→
    70→  // PUT /api/todos/:id - Update a todo
    71→  server.put('/api/todos/:id', (req) async {
    72→    final authResult = await authMiddleware(req);
    73→    if (authResult != null) return authResult;
    74→
    75→    final user = req.context['user'] as User;
    76→    final id = int.tryParse(req.params['id'] ?? '');
    77→    if (id == null) {
    78→      return ApiResponse.badRequest('Invalid ID');
    79→    }
    80→
    81→    final todo = await Model<Todo>().find(id);
    82→    if (todo == null || todo.userId != user.id) {
    83→      return ApiResponse.notFound('Todo not found');
    84→    }
    85→
    86→    final body = req.json;
    87→    if (body == null) {
    88→      return ApiResponse.badRequest('Request body required');
    89→    }
    90→
    91→    todo.title = (body['title'] as String?)?.trim() ?? todo.title;
    92→    todo.completed = body['completed'] as bool? ?? todo.completed;
    93→
    94→    await todo.save();
    95→    return ApiResponse.ok({'todo': todo.toJson()});
    96→  });
    97→
    98→  // DELETE /api/todos/:id - Delete a todo
    99→  server.delete('/api/todos/:id', (req) async {
   100→    final authResult = await authMiddleware(req);
   101→    if (authResult != null) return authResult;
   102→
   103→    final user = req.context['user'] as User;
   104→    final id = int.tryParse(req.params['id'] ?? '');
   105→    if (id == null) {
   106→      return ApiResponse.badRequest('Invalid ID');
   107→    }
   108→
   109→    final todo = await Model<Todo>().find(id);
   110→    if (todo == null || todo.userId != user.id) {
   111→      return ApiResponse.notFound('Todo not found');
   112→    }
