107→String? _extractCookie(String cookieHeader, String name) {
108→  final cookies = cookieHeader.split(';');
109→  for (final cookie in cookies) {
110→    final parts = cookie.trim().split('=');
111→    if (parts.length == 2 && parts[0].trim() == name) {
112→      return parts[1].trim();
113→    }
114→  }
115→  return null;
116→}
