     3→
     4→/// Extracts the session_token cookie, validates the session, and attaches
     5→/// the authenticated User to `req.context['user']`.
     6→/// Returns an ApiResponse(401) if the session is missing or invalid.
     7→Future<ApiResponse?> authMiddleware(ApiRequest req) async {
     8→  final cookieHeader = req.headers['cookie'] ?? '';
     9→  final token = _extractCookie(cookieHeader, 'session_token');
    10→
    11→  if (token == null || token.isEmpty) {
    12→    return ApiResponse.unauthorized('Authentication required');
    13→  }
    14→
    15→  final user = await SessionManager.getUserFromToken(token);
    16→  if (user == null) {
    17→    return ApiResponse.unauthorized('Invalid or expired session');
    18→  }
    19→
    20→  req.context['user'] = user;
    21→  return null; // continue to route handler
    22→}
    23→
    24→String? _extractCookie(String cookieHeader, String name) {
    25→  final cookies = cookieHeader.split(';');
    26→  for (final cookie in cookies) {
    27→    final parts = cookie.trim().split('=');
    28→    if (parts.length == 2 && parts[0].trim() == name) {
    29→      return parts[1].trim();
    30→    }
    31→  }
    32→  return null;
    33→}
