    // Register models
    Post.register();
    User.register();
    Todo.register();
    Session.register();

    // Initialize ORM with SQLite
    final dataDir = Platform.environment['DATA_DIR'] ?? '.';
    await DuxtOrm.init((
      driver: 'sqlite',
      host: '',
      port: 0,
      database: '',
      username: '',
      password: '',
      path: '$dataDir/app.db',
      ssl: false,
    ));

    // Run migrations (creates tables)
    await DuxtOrm.migrate();
  }
}

import 'dart:io';
import 'package:duxt/server.dart';
import 'db.dart';
import 'api/auth.dart';
import 'api/todos.dart';

void main() async {
  // Initialize ORM and run migrations
  await Db.init();

  final port = int.tryParse(Platform.environment['PORT'] ?? '') ?? 3001;

  final server = DuxtServer(
    port: port,
    middleware: [
      securityHeaders(),
      bodyLimit(),
      cors(origins: ['http://localhost:4000']),
      jsonBody(),
      logger(),
    ],
  );

  // Register API routes
  registerAuthApi(server);
  registerTodoApi(server);

  server.start();
}

