 12→    final body = req.body as Map<String, dynamic>?;
 13→    if (body == null) {
 14→      return json({'error': 'Request body required'}, statusCode: 400);
 15→    }
 16→
 17→    final email = (body['email'] as String?)?.trim();
 18→    final password = body['password'] as String?;
 19→    final name = (body['name'] as String?)?.trim();
 20→
 21→    if (email == null || email.isEmpty) {
 22→      return json({'error': 'Email is required'}, statusCode: 400);
 23→    }
 24→    if (password == null || password.length < 6) {
 25→      return json({'error': 'Password must be at least 6 characters'},
 26→          statusCode: 400);
 27→    }
 28→    if (name == null || name.isEmpty) {
 29→      return json({'error': 'Name is required'}, statusCode: 400);
 30→    }
 31→
 32→    // Check for existing user
 33→    final existing = await User.findByEmail(email);
 34→    if (existing != null) {
 35→      return json({'error': 'Email already registered'}, statusCode: 409);
 36→    }
 37→
 38→    // Create user
 39→    final hashedPassword = PasswordHelper.hash(password);
 40→    final user = User(
 41→      email: email,
 42→      password: hashedPassword,
 43→      name: name,
 44→    );
 45→    await user.save();
 46→
 47→    // Create session
 48→    final token = await SessionManager.createSession(user.id as int);
 49→
 50→    return json(
 51→      {'user': user.toSafeMap()},
 52→      statusCode: 201,
 53→      headers: {'Set-Cookie': 'session_token=$token; $_cookieFlags'},
 54→    );
 55→  });
 56→
 57→  // POST /api/auth/login
 58→  server.post('/api/auth/login', (req) async {
 59→    final body = req.body as Map<String, dynamic>?;
 60→    if (body == null) {
 61→      return json({'error': 'Request body required'}, statusCode: 400);
 62→    }
 63→
 64→    final email = (body['email'] as String?)?.trim();
 65→    final password = body['password'] as String?;
 66→
 67→    if (email == null ||
 68→        email.isEmpty ||
 69→        password == null ||
 70→        password.isEmpty) {
 71→      return json({'error': 'Email and password are required'},
 72→          statusCode: 400);
 73→    }
