 1→import 'package:dbcrypt/dbcrypt.dart';
 2→
 3→class PasswordHelper {
 4→  static final _bcrypt = DBCrypt();
 5→
 6→  static String hash(String password) {
 7→    final salt = _bcrypt.gensaltWithRounds(12);
 8→    return _bcrypt.hashpw(password, salt);
 9→  }
10→
11→  static bool verify(String password, String hashed) {
12→    return _bcrypt.checkpw(password, hashed);
13→  }
14→}
