 59→      return json({'error': 'Invalid ID'}, statusCode: 400);
 60→    }
 61→
 62→    final todo = await Model<Todo>().find(id);
 63→    if (todo == null || todo.userId != user.id) {
 64→      return json({'error': 'Todo not found'}, statusCode: 404);
 65→    }
