 70→  // PUT /api/todos/:id - Update a todo
 71→  server.put('/api/todos/:id', (req) async {
 72→    final user = await getAuthUser(req);
 73→    if (user == null) {
 74→      return json({'error': 'Authentication required'}, statusCode: 401);
