 81→
 82→    final todo = await Model<Todo>().find(id);
 83→    if (todo == null || todo.userId != user.id) {
 84→      return json({'error': 'Todo not found'}, statusCode: 404);
 85→    }
 86→
 87→    final body = req.body as Map<String, dynamic>?;
 88→    if (body == null) {
 89→      return json({'error': 'Request body required'}, statusCode: 400);
 90→    }
 91→
 92→    todo.title = (body['title'] as String?)?.trim() ?? todo.title;
 93→    todo.completed = body['completed'] as bool? ?? todo.completed;
 94→
 95→    await todo.save();
 96→    return json({'todo': todo.toJson()});
 97→  });
