 99→  // DELETE /api/todos/:id - Delete a todo
100→  server.delete('/api/todos/:id', (req) async {
101→    final user = await getAuthUser(req);
102→    if (user == null) {
103→      return json({'error': 'Authentication required'}, statusCode: 401);
104→    }
105→
