 1→import 'package:shelf/shelf.dart';
 2→import 'package:todo/models/user.dart';
 3→import '../utils/session_manager.dart';
 4→
 5→/// Extracts the session_token cookie, validates the session, and returns
 6→/// the authenticated User or null if invalid.
 7→Future<User?> getAuthUser(Request req) async {
 8→  final cookieHeader = req.headers['cookie'] ?? '';
 9→  final token = extractCookie(cookieHeader, 'session_token');
10→
11→  if (token == null || token.isEmpty) return null;
12→
13→  return SessionManager.getUserFromToken(token);
14→}
15→
16→String? extractCookie(String cookieHeader, String name) {
17→  final cookies = cookieHeader.split(';');
18→  for (final cookie in cookies) {
19→    final parts = cookie.trim().split('=');
20→    if (parts.length == 2 && parts[0].trim() == name) {
21→      return parts[1].trim();
22→    }
23→  }
24→  return null;
25→}
