 1→import 'package:duxt_orm/duxt_orm.dart';
 2→import 'package:uuid/uuid.dart';
 3→import 'package:todo/models/session.dart';
 4→import 'package:todo/models/user.dart';
 5→
 6→class SessionManager {
 7→  static const _sessionDuration = Duration(hours: 24);
 8→  static final _uuid = Uuid();
 9→
10→  /// Creates a new session for the given user ID and returns the token.
11→  static Future<String> createSession(int userId) async {
12→    final token = _uuid.v4();
13→    final expiresAt = DateTime.now().add(_sessionDuration).toIso8601String();
14→
15→    final session = Session(
16→      token: token,
17→      userId: userId,
18→      expiresAt: expiresAt,
19→    );
20→    await session.save();
21→
22→    return token;
23→  }
24→
25→  /// Looks up a session by token and returns the associated User, or null.
26→  static Future<User?> getUserFromToken(String token) async {
27→    final session =
28→        await Model<Session>().query().where('token', token).first();
29→
30→    if (session == null || session.isExpired) {
31→      // Clean up expired session
32→      if (session != null) await session.forceDelete();
33→      return null;
34→    }
35→
36→    return Model<User>().find(session.userId);
37→  }
38→
39→  /// Deletes a session by token (logout).
40→  static Future<void> deleteSession(String token) async {
41→    final session =
42→        await Model<Session>().query().where('token', token).first();
43→    if (session != null) {
44→      await session.forceDelete();
45→    }
46→  }
47→}
