 8→    final posts = await Post.findAll(publishedOnly: true);
 9→    return json({'posts': posts.map((p) => p.toJson()).toList()});
10→  });
11→
12→  // GET /api/posts/:slug - Get single post by slug
13→  server.get('/api/posts/:slug', (req) async {
14→    final slug = req.params['slug'];
15→    if (slug == null) return json({'error': 'Slug required'}, statusCode: 400);
16→
17→    final post = await Post.findBySlug(slug);
18→    if (post == null) return json({'error': 'Not found'}, statusCode: 404);
19→
20→    return json({'post': post.toJson()});
21→  });
22→
23→  // POST /api/posts - Create new post
24→  server.post('/api/posts', (req) async {
25→    final body = req.body as Map<String, dynamic>?;
26→    if (body == null) return json({'error': 'Body required'}, statusCode: 400);
27→
28→    try {
29→      final post = Post.fromJson(body);
30→      await post.save();
31→      return json({'post': post.toJson()}, statusCode: 201);
32→    } catch (e) {
33→      print('Create failed: $e');
34→      return json({'error': 'Invalid request data'}, statusCode: 400);
35→    }
36→  });
37→
38→  // PUT /api/posts/:id - Update post
39→  server.put('/api/posts/:id', (req) async {
40→    final id = int.tryParse(req.params['id'] ?? '');
41→    if (id == null) return json({'error': 'Invalid ID'}, statusCode: 400);
42→
43→    final body = req.body as Map<String, dynamic>?;
44→    if (body == null) return json({'error': 'Body required'}, statusCode: 400);
45→
46→    final post = await Model<Post>().find(id);
47→    if (post == null) return json({'error': 'Not found'}, statusCode: 404);
48→
49→    // Update fields
50→    post.title = body['title'] as String? ?? post.title;
51→    post.slug = body['slug'] as String? ?? post.slug;
52→    post.content = body['content'] as String? ?? post.content;
53→    post.excerpt = body['excerpt'] as String? ?? post.excerpt;
54→    post.published = body['published'] as bool? ?? post.published;
55→
56→    await post.save();
57→    return json({'post': post.toJson()});
58→  });
59→
60→  // DELETE /api/posts/:id - Delete post
61→  server.delete('/api/posts/:id', (req) async {
62→    final id = int.tryParse(req.params['id'] ?? '');
63→    if (id == null) return json({'error': 'Invalid ID'}, statusCode: 400);
64→
65→    final post = await Model<Post>().find(id);
66→    if (post == null) return json({'error': 'Not found'}, statusCode: 404);
67→
68→    await post.destroy();
69→    return json({'success': true});
70→  });
